        Mutation('requireForce=false is not checked', 'if ! seen interactive && [ "$("$real" "${GLOBALS[@]}" config --type=bool --get clean.requireForce 2>/dev/null)" = "false" ]; then', 'if false; then', 'requireForce is off'),
        Mutation('rm of the root is not refused', 'if is_root_path "$p"; then RULE="git rm of the repository', 'if false; then RULE="git rm of the repository', 'stash drop and clear'),
        Mutation('rm --cached is refused', '      seen cached && return 0; seen dry-run && return 0', '      seen dry-run && return 0', 'stash drop and clear'),
